import openpyxl

wb = openpyxl.load_workbook('output.xlsx')
ws = wb['Sheet1']

for r in range(4, 7):
    first_col = None
    second_col = None
    for c in ws[r].iter_cells(min_col=2, max_col=13):
        if isinstance(c.value, (int, float)):
            if first_col is None:
                first_col = c.column
            else:
                second_col = c.column
                break
    if first_col is None or second_col is None:
        continue
    count = second_col - first_col - 1
    if ws.cell(row=r, column=1).value > 1:
        count = 1
    ws.cell(row=r, column=14).value = count

wb.save('output.xlsx')
print("done")

